insert into public.order_lines (order_id, product_id, qty, unit_price_vnd, line_total_vnd)
select v.oid, p.id, v.qty, v.price, v.lt
from v
join public.orders o on o.id = v.oid
join public.outlets ot on ot.id = o.outlet_id
join public.products p on p.org_id = ot.org_id and p.code = v.pcode
where not exists (select 1 from public.order_lines x where x.order_id = v.oid);

do $$ begin
  if (select count(*) from orders where outlet_id='3e1f4df8-6dcb-4593-85a4-2bef47468f42' and import_ref='knote') <> 72 then raise exception 'Knote: số đơn lệch'; end if;
  if (select count(*) from order_lines l join orders o on o.id=l.order_id where o.outlet_id='3e1f4df8-6dcb-4593-85a4-2bef47468f42' and o.import_ref='knote') <> 153 then raise exception 'Knote: số dòng lệch (có mã món không khớp?)'; end if;
